content.arguments:
{"code": "const cmd = `
$ErrorActionPreference='Continue'
Write-Output '--- home dirs ---'
Get-ChildItem $env:USERPROFILE -Directory -Force -ErrorAction SilentlyContinue | Select-Object -First 40 Name
Write-Output '--- .dsh anywhere in D:\\lean (top) ---'
Get-ChildItem D:\\lean -Directory -Force -ErrorAction SilentlyContinue | Where-Object { $_.Name -like '.*' } | Select-Object Name
Write-Output '--- env ---'
Write-Output $env:USERPROFILE
Write-Output $env:LOCALAPPDATA
Write-Output $env:APPDATA
Write-Output '--- dsh data candidates ---'
foreach ($d in @((Join-Path $env:USERPROFILE '.dsh'), (Join-Path $env:APPDATA 'dsh'), (Join-Path $env:LOCALAPPDATA 'dsh'), (Join-Path $env:USERPROFILE '.deepseek'))) { if (Test-Path $d) { Write-Output ('EXISTS ' + $d); Get-ChildItem $d -Force | Select-Object -First 10 Name } else { Write-Output ('absent ' + $d) } }
`;
const r = await tools.pwsh({ description: "Look for DSH session data directories", command: cmd, workdir: "D:\\lean", timeoutMs: 120000 });
console.log(r.kind==="foreground" ? r.stdout.text.slice(0,3000) + "\n[stderr]\n" + r.stderr.text.slice(0,500) : JSON.stringify(r));
", "description": "Look for DSH session store to recover ledger text"}

